import { defineUserConfig } from "vuepress";
import { getDirname, path } from 'vuepress/utils'
import { viteBundler } from "@vuepress/bundler-vite";
import { registerComponentsPlugin } from '@vuepress/plugin-register-components'

import theme from "./theme.js";
const __dirname = import.meta.dirname || getDirname(import.meta.url)

export default defineUserConfig({
  base: "/",

  // API docs are generated by DocFX into public/api. Ignore the legacy
  // src/api output, whose Index.md member pages can collide with type pages.
  pagePatterns: ["**/*.md", "!.vuepress", "!node_modules", "!api/**"],

  locales: {
    "/": {
      lang: "zh-CN",
      title: "neo-bpsys-wpf",
      description: "第五人格民间赛专属的直播BP展示工具",
    },
    "/en/": {
      lang: "en-US",
      title: "neo-bpsys-wpf",
      description: "A Identity V BP display tool for unofficial tournaments",
    },
    "/ja/": {
      lang: "ja-JP",
      title: "neo-bpsys-wpf",
      description: "第五人格非公式大会専用のライブBP展示ツールです",
    }
  },

  theme,

  plugins :[
    registerComponentsPlugin({
      components: {
        HomeLanding: path.resolve(__dirname, './components/HomeLanding.vue'),
      },
    }),
  ],

  bundler: viteBundler({
    viteOptions: {
      build: {
        rollupOptions: {
          output: {
            assetFileNames: (asset) => {
              const name = asset.names?.[0] ?? "";
              const original = (
                asset.originalFileNames?.[0] ?? ""
              ).replace(/\\/g, "/");

              // 匹配 user-guide 目录内的图片
              const match = original.match(
                /(?:^|\/)user-guide\/(.+)$/
              );

              if (
                match &&
                /\.(png|jpe?g|webp|gif|svg|avif)$/i.test(name)
              ) {
                const relativePath = match[1].replace(
                  /\.[^/.]+$/,
                  ""
                );

                return `user-guide/${relativePath}[extname]`;
              }

              // 其他静态资源保留哈希
              return "assets/[name]-[hash][extname]";
            },
          },
        },
      },
    },
  }),
  // Enable it with pwa
  // shouldPrefetch: false,
});
